#!/usr/bin/env python3
"""Build an offline metadata browser; no status or payout inference."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
m=json.loads((ROOT/'erdos-manifest.json').read_text())
keys=['number','problem_url','informal_status','derived_status','ordinary_unresolved_label','official_prize_listed','official_display_dollars','community_prize_raw','statement_formalized','statement_url','formal_solution_status','tags']
rows=[{k:e.get(k) for k in keys} for e in m['entries']]
data=json.dumps(rows,ensure_ascii=True,separators=(',',':')).replace('<','\\u003c')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Erdős catalog screening</title><style>
*{box-sizing:border-box}body{margin:0;font:16px/1.5 system-ui,sans-serif;color:#18332c;background:#f4f5ef}main{max-width:1250px;margin:auto;padding:40px 24px}h1{font-size:36px;line-height:1.15}p{max-width:900px}a{color:#076a60}small{color:#5b6a62}.note{background:#fff2cf;border-left:4px solid #a36e14;padding:15px 20px}.filters{display:flex;gap:16px;flex-wrap:wrap;align-items:center;background:white;border:1px solid #d6dfd6;padding:16px;margin:24px 0}input[type=search]{font:inherit;padding:9px;width:250px}select{font:inherit;padding:8px}button{font:inherit;padding:8px 14px;background:#173e33;color:white;border:0;border-radius:4px}table{border-collapse:collapse;width:100%;background:white}th,td{padding:10px 13px;text-align:left;border-bottom:1px solid #dde3db;font-size:14px}th{position:sticky;top:0;background:#e1ebe3}td:nth-child(1){font-weight:700}#count{font-weight:650;margin:12px 0}.table{overflow:auto}footer{margin-top:25px;font-size:13px;color:#52665a}</style><main><small>Research screening snapshot · 17 October 2026</small><h1>The full current Erdős catalog</h1><p>1,221 entries from the pinned community metadata catalog, reconciled with the site's prize pages. This is not every question Erdős ever posed. Problem statements and discussions remain at their source links.</p><div class="note"><strong>Listed rewards are historical/source claims, not verified payable prizes.</strong> Status comes from the community database; the main site stopped displaying statuses on October 6. A formalized statement is not a proof. Read the statement, recent discussion and literature before attempting a problem.</div><div class="filters"><label>Search ID or subject<br><input id="query" type="search" placeholder="e.g. 128, graph theory"></label><label><input id="open" type="checkbox" checked> Ordinary unresolved labels</label><label><input id="prize" type="checkbox" checked> Listed on prize pages</label><label>Lean statement<br><select id="lean"><option value="">Either</option><option value="yes">Recorded</option><option value="no">Not recorded</option></select></label><button id="all">Show all 1,221</button><button id="reset">Prize screening set</button></div><p id="count" aria-live="polite"></p><div class="table"><table><thead><tr><th>Problem</th><th>Community status</th><th>Listed reward</th><th>Subject</th><th>Lean statement</th><th>Solution tag</th></tr></thead><tbody id="rows"></tbody></table></div><footer>Unresolved filter: open, falsifiable, verifiable, decidable. It excludes other nuanced states; use Show all to inspect them. No difficulty or solvability probability is inferred. <a href="erdos-manifest.csv">CSV</a> · <a href="erdos-manifest.json">Full JSON and provenance</a> · <a href="shortlist.html">Research shortlist</a><br>Community revision: REVISION</footer></main><script id="data" type="application/json">DATA</script><script>
const entries=JSON.parse(document.getElementById('data').textContent);
const el=id=>document.getElementById(id);
function cell(row,text){const c=document.createElement('td');c.textContent=text;row.appendChild(c);return c}
function link(c,text,url){const a=document.createElement('a');a.textContent=text;a.href=url;a.target='_blank';a.rel='noopener noreferrer';c.appendChild(a)}
function render(){const q=el('query').value.trim().toLowerCase();const rows=entries.filter(e=>(!el('open').checked||e.ordinary_unresolved_label)&&(!el('prize').checked||e.official_prize_listed)&&(!el('lean').value||e.statement_formalized===el('lean').value)&&(!q||e.number===q||(e.tags||[]).join(' ').toLowerCase().includes(q)));el('count').textContent=`${rows.length} of ${entries.length} entries shown — metadata screening only`;const frag=document.createDocumentFragment();for(const e of rows){const r=document.createElement('tr');link(cell(r,''),'#'+e.number,e.problem_url);cell(r,e.derived_status||e.informal_status||'Unknown');cell(r,e.official_prize_listed?'$'+e.official_display_dollars+' · unverified payout':e.community_prize_raw&&e.community_prize_raw!=='no'?e.community_prize_raw+' · community only':'No listed reward');cell(r,(e.tags||[]).join(', '));const c=cell(r,'');if(e.statement_formalized==='yes'&&e.statement_url)link(c,'Statement',e.statement_url);else c.textContent=e.statement_formalized||'Unknown';cell(r,e.formal_solution_status||'Unknown');frag.appendChild(r)}el('rows').replaceChildren(frag)}
for(const id of ['query','open','prize','lean'])el(id).addEventListener('input',render);
el('all').onclick=()=>{el('open').checked=false;el('prize').checked=false;el('query').value='';el('lean').value='';render()};
el('reset').onclick=()=>{el('open').checked=true;el('prize').checked=true;el('query').value='';el('lean').value='';render()};render();
</script></html>'''
html=html.replace('REVISION',m['revision']).replace('DATA',data)
(ROOT/'erdos-catalog.html').write_text(html)
assert len(rows)==1221 and len({e['number'] for e in rows})==1221
assert sum(bool(e['ordinary_unresolved_label'] and e['official_prize_listed']) for e in rows)==59
print('Built offline1221-entry browser; default screening59entries; no payout inference.')
